INSERT INTO `wf_logic_flow` (`id`, `created_at`, `description`, `dsl_json`, `flow_key`, `name`, `status`, `tenant_id`, `updated_at`, `version`) VALUES ('31466d6915d44c5dab2e00821233a24f', '2026-10-11 16:06:31.518530', '演示：审批通过(流程结束)后自动建档并累加年假台账（DATA_UPSERT + DATA_UPDATE）', '{"nodes":[{"id":"start1","type":"START","name":"开始","x":80,"y":60},{"id":"dq_ledger","type":"DATA_QUERY","name":"查询台账是否已建档","x":80,"y":176,"config":{"formKey":"leave_ledger_demo","filter":[{"column":"employeeName","value":"{{formData.applicant}}"}],"size":1},"results":[{"name":"total","mode":"KEY","type":"number","desc":"命中行数"}],"errorAction":"FAIL_FLOW"},{"id":"cond_empty","type":"CONDITION","name":"台账不存在?","x":80,"y":310,"config":{"variable":"total","operator":"EQ","value":"0"}},{"id":"di_create","type":"DATA_INSERT","name":"首次自动建档(总额10天)","x":80,"y":426,"config":{"formKey":"leave_ledger_demo","data":[{"column":"employeeName","value":"{{formData.applicant}}"},{"column":"department","value":"{{formData.department}}"},{"column":"annualDays","value":"10"},{"column":"usedDays","value":"0"}]},"errorAction":"FAIL_FLOW"},{"id":"du_add","type":"DATA_UPDATE","name":"累加已用天数","x":80,"y":542,"config":{"table":"","setOps":[],"where":[],"updates":[{"table":"wf_biz_leave_ledger_demo","setOps":[{"column":"usedDays","mode":"ADD","value":"{{formData.days}}"}],"where":[{"column":"employeeName","op":"EQ","value":"{{formData.applicant}}"}]}]},"errorAction":"FAIL_FLOW"},{"id":"end1","type":"END","name":"结束","x":80,"y":658}],"edges":[{"source":"start1","target":"dq_ledger","id":"e1"},{"source":"dq_ledger","target":"cond_empty","id":"e2"},{"source":"du_add","target":"end1","id":"e6"},{"source":"cond_empty","target":"du_add","id":"vueflow__edge-cond_emptytrue-du_add","branch":"true"},{"source":"cond_empty","target":"di_create","id":"vueflow__edge-cond_emptyfalse-di_createin","branch":"false"},{"source":"di_create","target":"du_add","id":"vueflow__edge-di_createout-du_add"}]}', 'leave_ledger_sync', '请假批准同步年假台账', 'PUBLISHED', 'default', '2026-10-11 16:34:07.183112', '9') ON DUPLICATE KEY UPDATE `created_at`=VALUES(`created_at`), `description`=VALUES(`description`), `dsl_json`=VALUES(`dsl_json`), `flow_key`=VALUES(`flow_key`), `name`=VALUES(`name`), `status`=VALUES(`status`), `tenant_id`=VALUES(`tenant_id`), `updated_at`=VALUES(`updated_at`), `version`=VALUES(`version`);
